// Fonts for roto-demo, subset to what the film prints and embedded so index.html works straight from disk.
// Anton, Shippori Mincho B1 (ExtraBold) and JetBrains Mono: SIL Open Font License 1.1 (fonts/OFL-*.txt), from github.com/google/fonts.
// To add characters: pyftsubset <font>.ttf --unicodes=U+0020-007E --text="…" --flavor=woff, then re-embed.
MV.onInit(async () => {
  const faces = [
    ['Anton', 'data:font/woff;base64,', {}],
    ['Shippori Mincho B1', 'data:font/woff;base64,', { weight: '800' }],
    ['JetBrains Mono', 'data:font/woff;base64,', { weight: '100 800' }],
  ];
  for (const [family, url, desc] of faces) { const ff = new FontFace(family, `url(${url})`, desc); await ff.load(); document.fonts.add(ff); }
});
